  const fileToData = f => new Promise((ok, no) => { if (f.size > 8e6) return no(new Error('that image is too big')); const img = new Image(), u = URL.createObjectURL(f); img.onload = () => { const s = Math.min(512, Math.max(img.width, img.height)), c = document.createElement('canvas'), k = s / Math.max(img.width, img.height); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k); c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(u); ok(f.type === 'image/gif' ? null : c.toDataURL(f.type === 'image/jpeg' ? 'image/jpeg' : 'image/png', .9)); }; img.onerror = () => no(new Error('that file isn’t an image')); img.src = u; });
